// Shared classroom path policy. The API copy is generated by build-learning-path-sequence.mjs.

export const sequenceMillis = value => typeof value === 'number' && Number.isFinite(value) ? value : value?.toMillis?.() ?? (typeof value?.seconds === 'number' ? value.seconds * 1000 : null);
export const openingDay = value => {
  const time = sequenceMillis(value);
  if (time === null) return null;
  return new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Manila', year: 'numeric', month: '2-digit', day: '2-digit' }).format(time);
};
export const effectiveOpening = path => sequenceMillis(path.openAt) ?? sequenceMillis(path.sequenceOpenAt) ?? sequenceMillis(path.createdAt) ?? sequenceMillis(path.assignedAt);
export function orderedPathAssignments(assignments = [], links = []) {
  const paths = new Map(assignments.filter(path => !path.archived).map(path => [path.id, { ...path }]));
  for (const link of links) {
    const id = link.learningPathAssignmentId;
    if (!id || assignments.some(path => path.id === id && path.archived)) continue;
    if (!paths.has(id)) paths.set(id, { id, title: link.learningPathTitle, mode: link.mode || (link.practice ? 'practice' : 'assessment'), order: link.learningPathOrder, openAt: link.openAt, sequenceOpenAt: link.sequenceOpenAt, createdAt: link.createdAt || link.assignedAt });
    const path = paths.get(id), order = Number(link.order);
    if (Number.isFinite(order) && order > 0) path.linkOrder = Math.min(path.linkOrder ?? Infinity, order);
  }
  return [...paths.values()].sort((a, b) => (a.order ?? a.linkOrder ?? Infinity) - (b.order ?? b.linkOrder ?? Infinity) || (sequenceMillis(a.createdAt) ?? 0) - (sequenceMillis(b.createdAt) ?? 0) || a.id.localeCompare(b.id));
}
export function pathScheduleError(paths, index) {
  const current = paths[index], previous = paths[index - 1], next = paths[index + 1];
  const day = openingDay(effectiveOpening(current));
  if (previous) {
    const before = openingDay(effectiveOpening(previous));
    if (!day || !before || day <= before) return `Opening date must be on a later calendar day than ${previous.title || 'the previous lesson path'}${before ? ' (' + before + ')' : ''}.`;
  }
  if (next) {
    const after = openingDay(effectiveOpening(next));
    if (!day || !after || day >= after) return `Opening date must be on an earlier calendar day than ${next.title || 'the next lesson path'}${after ? ' (' + after + ')' : ''}.`;
  }
  return null;
}
export const sequenceLessonComplete = lesson => lesson.lectureFinished === true && ['game', 'activity', 'pronunciation', 'quiz'].every(part => lesson[part + 'Finished'] === true || lesson[part + 'Skipped'] === true);
// Store prerequisite identities with downloads so a missing download cannot unlock a later path.
export function withPathPrerequisites(lessons) {
  const paths = orderedPathAssignments([], lessons);
  return lessons.map(lesson => {
    const index = paths.findIndex(path => path.id === lesson.learningPathAssignmentId);
    if (index < 0) return lesson;
    const previous = new Set(paths.slice(0, index).filter(path => path.mode !== 'practice').map(path => path.id));
    const siblings = pathModules(lessons.filter(item => item.learningPathAssignmentId === lesson.learningPathAssignmentId)).flatMap(module => module.members);
    const lessonPrerequisites = siblings.slice(0, siblings.findIndex(item => item.id === lesson.id))
      .filter(item => !item.practice && !item.exempt && !item.closedBeforeJoining)
      .map(item => ({ id: item.id, title: item.title, finished: sequenceLessonComplete(item) }));
    return { ...lesson, lessonPrerequisites, pathPrerequisites: lessons.filter(item => previous.has(item.learningPathAssignmentId) && !item.exempt && !item.closedBeforeJoining).map(item => ({ id: item.id, title: item.learningPathTitle, finished: sequenceLessonComplete(item), gameSkipped: item.gameSkipped, activitySkipped: item.activitySkipped, quizSkipped: item.quizSkipped, pronunciationSkipped: item.pronunciationSkipped })) };
  });
}
export function pathBlocker(lesson, lessons) {
  return lesson.pathPrerequisites?.find(required => {
    const current = lessons.find(item => item.id === required.id);
    return current ? !current.exempt && !sequenceLessonComplete(current) : required.finished !== true;
  }) || null;
}
export function canOpenPathLesson(lesson, lessons, time = Date.now()) {
  if (pathBlocker(lesson, lessons)) return false;
  if (sequenceBlocker(lesson, lessons)) return false;
  if (lesson.openAt != null && time < lesson.openAt) return false;
  return lesson.dueAt == null || time <= lesson.dueAt || sequenceLessonComplete(lesson);
}

export const lessonSequence = lessons => [...lessons].sort((a, b) =>
  (a.learningPathModuleOrder ?? a.moduleOrder ?? a.order ?? 0) - (b.learningPathModuleOrder ?? b.moduleOrder ?? b.order ?? 0) ||
  (a.order ?? 0) - (b.order ?? 0) || a.id.localeCompare(b.id));
export function pathModules(lessons) {
  const groups = new Map();
  for (const lesson of lessonSequence(lessons)) {
    const id = lesson.moduleId || '__lessons';
    if (!groups.has(id)) groups.set(id, { id, title: lesson.moduleTitle || 'Mga aralin', members: [] });
    groups.get(id).members.push(lesson);
  }
  return [...groups.values()];
}
export function sequenceBlocker(lesson, lessons) {
  if (!lesson.learningPathAssignmentId) return null;
  const missing = lesson.lessonPrerequisites?.find(required => {
    const current = lessons.find(item => item.id === required.id);
    return !current && required.finished !== true;
  });
  if (missing) return missing;
  const modules = pathModules(lessons.filter(item => item.learningPathAssignmentId === lesson.learningPathAssignmentId));
  const index = modules.findIndex(module => module.members.some(item => item.id === lesson.id));
  if (index < 0) return null;
  const incomplete = item => !item.exempt && !item.closedBeforeJoining && !item.practice && !sequenceLessonComplete(item);
  for (const module of modules.slice(0, index)) {
    if (module.members.some(incomplete)) return { title: module.title, kind: 'module' };
  }
  const members = modules[index].members;
  return members.slice(0, members.findIndex(item => item.id === lesson.id)).find(incomplete) || null;
}
